#!/usr/bin/env python3
"""Generate kpol/pyunicode_tables.go: Python str character-class tables.

The KPOL reference lexer classifies characters with str.isspace / isalpha /
isdigit / isalnum (decision D-K1), so the Go port freezes the same classes
instead of relying on the Unicode version of the Go toolchain.

Usage (from Engineering/sw/kpol-go):  python3 testdata/gen_pyunicode.py
"""

from __future__ import annotations

import sys
import unicodedata
from pathlib import Path

OUT = Path(__file__).resolve().parents[1] / "kpol" / "pyunicode_tables.go"


def is_scalar(cp: int) -> bool:
    return not 0xD800 <= cp <= 0xDFFF


def ranges(pred) -> list[tuple[int, int]]:
    out: list[tuple[int, int]] = []
    start = None
    for cp in range(0x110000):
        value = is_scalar(cp) and pred(chr(cp))
        if value and start is None:
            start = cp
        elif not value and start is not None:
            out.append((start, cp - 1))
            start = None
    if start is not None:
        out.append((start, 0x10FFFF))
    return out


def emit(name: str, doc: str, items: list[tuple[int, int]]) -> str:
    lines = [f"// {doc}", f"var {name} = []runeRange{{"]
    row: list[str] = []
    for lo, hi in items:
        row.append(f"{{0x{lo:04X}, 0x{hi:04X}}},")
        if len(row) == 4:
            lines.append("\t" + " ".join(row))
            row = []
    if row:
        lines.append("\t" + " ".join(row))
    lines.append("}")
    return "\n".join(lines)


def main() -> int:
    zeros = [cp for cp in range(0x110000)
             if is_scalar(cp) and chr(cp).isdecimal() and unicodedata.decimal(chr(cp)) == 0]
    parts = [
        "// Code generated by testdata/gen_pyunicode.py; DO NOT EDIT.",
        "",
        "package kpol",
        "",
        f"// pyUnicodeVersion is the Unicode version of Python {sys.version.split()[0]}"
        " used to generate the tables.",
        f'const pyUnicodeVersion = "{unicodedata.unidata_version}"',
        "",
        "// runeRange is an inclusive range of code points.",
        "type runeRange struct{ lo, hi rune }",
        "",
        emit("pySpaceTable", "pySpaceTable lists the code points with str.isspace() == True.",
             ranges(str.isspace)),
        "",
        emit("pyAlphaTable", "pyAlphaTable lists the code points with str.isalpha() == True.",
             ranges(str.isalpha)),
        "",
        emit("pyDigitTable", "pyDigitTable lists the code points with str.isdigit() == True.",
             ranges(str.isdigit)),
        "",
        emit("pyDecimalTable", "pyDecimalTable lists the code points with str.isdecimal() == True.",
             ranges(str.isdecimal)),
        "",
        emit("pyAlnumTable", "pyAlnumTable lists the code points with str.isalnum() == True.",
             ranges(str.isalnum)),
        "",
        emit("pyPrintableTable",
             "pyPrintableTable lists the code points with str.isprintable() == True.",
             ranges(str.isprintable)),
        "",
        "// pyDecimalZeros lists the code points whose decimal digit value is 0; every",
        "// decimal digit r satisfies r-z in 0..9 for the greatest zero z <= r.",
        "var pyDecimalZeros = []rune{",
    ]
    row = []
    for cp in zeros:
        row.append(f"0x{cp:04X},")
        if len(row) == 8:
            parts.append("\t" + " ".join(row))
            row = []
    if row:
        parts.append("\t" + " ".join(row))
    parts.append("}")
    OUT.write_text("\n".join(parts) + "\n", encoding="utf-8")
    print(f"wrote {OUT}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
